-- ═══════════════════════════════════════════════
-- SECTOR MODIFIERS
-- ═══════════════════════════════════════════════
insert into sector_modifiers (nation_id, sector, mod_mult)
select n.id, s.sector, s.mod_mult
from nations n
cross join (values
  ('Agriculture', 1.0), ('Heavy Industry', 1.5), ('Energy', 1.0),
  ('Consumer Goods', 1.5), ('Military & Aerospace', 1.0),
  ('Pharmaceuticals', 0.5), ('Transport & Trade', 2.5)
) as s(sector, mod_mult)
on conflict (nation_id, sector) do nothing;

