-- ═══════════════════════════════════════════════
-- ECO HISTORY (turn 0 snapshot)
-- ═══════════════════════════════════════════════
-- GDP = total_company_profits + QoL_tax_at_max_rate
-- QoL tax = 1,200,000,000 * (pop/40M) * (qol/50) * 0.80
insert into eco_history (nation_id, turn_number, gdp, treasury, qol)
select
  n.id, 0,
  (select coalesce(sum(profit), 0) from companies where nation_id = n.id)
    + round(1200000000.0 * (n.population::real / 40000000.0) * (n.qol::real / 50.0) * 0.80),
  n.gdp,
  n.qol
from nations n;

